const chunk = (name: string, data: number[] = []) => [
  0x00,
  0x00,
  0x00,
  data.length,
  ...name.split("").map((character) => character.charCodeAt(0)),
  ...data,
  0x00,
  0x00,
  0x00,
  0x00,
];

